+function diffLines(a, b) {
+  // Intern lines so the inner loops compare small integers, not strings.
+  const ids = new Map();
+  const intern = (lines) => {
+    const out = new Int32Array(lines.length);
+    for (let i = 0; i < lines.length; i++) {
+      let id = ids.get(lines[i]);
+      if (id === undefined) {
+        id = ids.size;
+        ids.set(lines[i], id);
+      }
+      out[i] = id;
+    }
+    return out;
+  };
+  const A = intern(a);
+  const B = intern(b);
+
+  // Raw script as parallel arrays: op code (0 equal, 1 delete, 2 insert) and index.
+  const codes = [];
+  const idx = [];
+  const EQUAL = 0;
+  const DELETE = 1;
+  const INSERT = 2;
+
+  /**
+   * Myers bisection: find a point on an optimal path through the box
+   * [aLo, aHi) x [bLo, bHi), whose ends share no common line. Returns the
+   * absolute split point, which is strictly inside the box when D >= 2.
+   */
+  function bisect(aLo, aHi, bLo, bHi) {
+    const n = aHi - aLo;
+    const m = bHi - bLo;
+    const maxD = (n + m + 1) >> 1;
+    const off = maxD + 1;
+    const len = 2 * maxD + 3;
+    const vf = new Int32Array(len).fill(-1);
+    const vr = new Int32Array(len).fill(-1);
+    vf[off + 1] = 0;
+    vr[off + 1] = 0;
+    const delta = n - m;
+    const front = (delta & 1) !== 0;
+    let kfStart = 0;
+    let kfEnd = 0;
+    let krStart = 0;
+    let krEnd = 0;
+    for (let d = 0; d <= maxD; d++) {
+      for (let k = -d + kfStart; k <= d - kfEnd; k += 2) {
+        const ko = off + k;
+        let x = k === -d || (k !== d && vf[ko - 1] < vf[ko + 1]) ? vf[ko + 1] : vf[ko - 1] + 1;
+        let y = x - k;
+        while (x < n && y < m && A[aLo + x] === B[bLo + y]) {
+          x++;
+          y++;
+        }
+        vf[ko] = x;
+        if (x > n) {
+          kfEnd += 2;
+        } else if (y > m) {
+          kfStart += 2;
+        } else if (front) {
+          const kro = off + delta - k;
+          if (kro >= 0 && kro < len && vr[kro] !== -1 && x >= n - vr[kro]) {
+            return [aLo + x, bLo + y];
+          }
+        }
+      }
+      for (let k = -d + krStart; k <= d - krEnd; k += 2) {
+        const ko = off + k;
+        let x = k === -d || (k !== d && vr[ko - 1] < vr[ko + 1]) ? vr[ko + 1] : vr[ko - 1] + 1;
+        let y = x - k;
+        while (x < n && y < m && A[aHi - 1 - x] === B[bHi - 1 - y]) {
+          x++;
+          y++;
+        }
+        vr[ko] = x;
+        if (x > n) {
+          krEnd += 2;
+        } else if (y > m) {
+          krStart += 2;
+        } else if (!front) {
+          const kfo = off + delta - k;
+          if (kfo >= 0 && kfo < len && vf[kfo] !== -1) {
+            const xf = vf[kfo];
+            if (xf >= n - x) return [aLo + xf, bLo + xf - (delta - k)];
+          }
+        }
+      }
+    }
+    throw new Error('diffLines: no middle snake found');
+  }
+
+  function emitEqual(x, y, count) {
+    for (let i = 0; i < count; i++) {
+      codes.push(EQUAL);
+      idx.push(x + i);
+    }
+  }
+
+  function rec(aLo, aHi, bLo, bHi) {
+    let prefix = 0;
+    while (aLo + prefix < aHi && bLo + prefix < bHi && A[aLo + prefix] === B[bLo + prefix]) prefix++;
+    emitEqual(aLo, bLo, prefix);
+    aLo += prefix;
+    bLo += prefix;
+    let suffix = 0;
+    while (aHi - suffix > aLo && bHi - suffix > bLo && A[aHi - 1 - suffix] === B[bHi - 1 - suffix]) suffix++;
+    aHi -= suffix;
+    bHi -= suffix;
+    if (aLo === aHi) {
+      for (let y = bLo; y < bHi; y++) {
+        codes.push(INSERT);
+        idx.push(y);
+      }
+    } else if (bLo === bHi) {
+      for (let x = aLo; x < aHi; x++) {
+        codes.push(DELETE);
+        idx.push(x);
+      }
+    } else {
+      const [x, y] = bisect(aLo, aHi, bLo, bHi);
+      rec(aLo, x, bLo, y);
+      rec(x, aHi, y, bHi);
+    }
+    emitEqual(aHi, bHi, suffix);
+  }
+
+  rec(0, A.length, 0, B.length);
+
+  // Build the result, ordering deletes before inserts within each change region.
+  const script = [];
+  const pendingInserts = [];
+  for (let i = 0; i < codes.length; i++) {
+    const code = codes[i];
+    if (code === INSERT) {
+      pendingInserts.push(idx[i]);
+      continue;
+    }
+    if (code === EQUAL) {
+      for (const y of pendingInserts) script.push({ op: 'insert', line: b[y] });
+      pendingInserts.length = 0;
+      script.push({ op: 'equal', line: a[idx[i]] });
+    } else {
+      script.push({ op: 'delete', line: a[idx[i]] });
+    }
+  }
+  for (const y of pendingInserts) script.push({ op: 'insert', line: b[y] });
+  return script;
+}
