+function unifiedHunks(a, b, { context = 3 } = {}) {
+  if (!Number.isInteger(context) || context < 0) {
+    throw new RangeError('context must be a nonnegative integer');
+  }
+  const script = diffLines(a, b);
+
+  // Maximal change regions as [start, end) script indices.
+  const regions = [];
+  for (let i = 0; i < script.length; ) {
+    if (script[i].op === 'equal') {
+      i++;
+      continue;
+    }
+    const start = i;
+    while (i < script.length && script[i].op !== 'equal') i++;
+    regions.push([start, i]);
+  }
+
+  // old/new line counts consumed before each script index.
+  const oldBefore = new Int32Array(script.length + 1);
+  const newBefore = new Int32Array(script.length + 1);
+  for (let i = 0; i < script.length; i++) {
+    const op = script[i].op;
+    oldBefore[i + 1] = oldBefore[i] + (op === 'insert' ? 0 : 1);
+    newBefore[i + 1] = newBefore[i] + (op === 'delete' ? 0 : 1);
+  }
+
+  const prefixes = { equal: ' ', delete: '-', insert: '+' };
+  const hunks = [];
+  for (let r = 0; r < regions.length; ) {
+    let last = r;
+    while (last + 1 < regions.length && regions[last + 1][0] - regions[last][1] <= 2 * context) last++;
+    const from = Math.max(0, regions[r][0] - context);
+    const to = Math.min(script.length, regions[last][1] + context);
+    const lines = [];
+    for (let i = from; i < to; i++) lines.push(prefixes[script[i].op] + script[i].line);
+    const oldLines = oldBefore[to] - oldBefore[from];
+    const newLines = newBefore[to] - newBefore[from];
+    hunks.push({
+      oldStart: oldLines === 0 ? oldBefore[from] : oldBefore[from] + 1,
+      oldLines,
+      newStart: newLines === 0 ? newBefore[from] : newBefore[from] + 1,
+      newLines,
+      lines,
+    });
+    r = last + 1;
+  }
+  return hunks;
+}
