+function applyHunks(a, hunks) {
+  if (!Array.isArray(hunks)) throw new TypeError('hunks must be an array');
+  const out = [];
+  let cursor = 0; // next unconsumed index in a
+  for (let h = 0; h < hunks.length; h++) {
+    const fail = (why) => new Error(`hunk ${h} does not apply: ${why}`);
+    const hunk = hunks[h];
+    if (hunk === null || typeof hunk !== 'object' || !Array.isArray(hunk.lines)) throw fail('malformed hunk');
+    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
+    for (const v of [oldStart, oldLines, newStart, newLines]) {
+      if (!Number.isInteger(v) || v < 0) throw fail('malformed coordinates');
+    }
+    if (lines.length === 0) throw fail('no lines');
+    let oldCount = 0;
+    let newCount = 0;
+    for (const line of lines) {
+      if (typeof line !== 'string' || line.length === 0) throw fail('malformed line');
+      const p = line[0];
+      if (p === ' ') {
+        oldCount++;
+        newCount++;
+      } else if (p === '-') {
+        oldCount++;
+      } else if (p === '+') {
+        newCount++;
+      } else {
+        throw fail('malformed line prefix');
+      }
+    }
+    if (oldCount !== oldLines || newCount !== newLines) throw fail('line counts do not match');
+    if (oldLines > 0 && oldStart === 0) throw fail('malformed old start');
+    if (newLines > 0 && newStart === 0) throw fail('malformed new start');
+    const start = oldLines === 0 ? oldStart : oldStart - 1;
+    if (start < cursor) throw fail('overlapping or out-of-order hunk');
+    if (start + oldLines > a.length) throw fail('old range exceeds input');
+    // New-side index of the hunk start: retained lines plus output so far.
+    const newIndex = out.length + (start - cursor);
+    if (newStart !== (newLines === 0 ? newIndex : newIndex + 1)) throw fail('new coordinates do not match');
+    let x = start;
+    for (const line of lines) {
+      if (line[0] !== '+' && a[x++] !== line.slice(1)) throw fail(`line ${x} does not match`);
+    }
+    for (let i = cursor; i < start; i++) out.push(a[i]);
+    for (const line of lines) {
+      if (line[0] !== '-') out.push(line.slice(1));
+    }
+    cursor = start + oldLines;
+  }
+  for (let i = cursor; i < a.length; i++) out.push(a[i]);
+  return out;
+}

