        oldCount++;
        newCount++;
      } else if (p === '-') {
        oldCount++;
      } else if (p === '+') {
        newCount++;
      } else {
        throw fail('malformed line prefix');
      }
    }
    if (oldCount !== oldLines || newCount !== newLines) throw fail('line counts do not match');
    if (oldLines > 0 && oldStart === 0) throw fail('malformed old start');
    if (newLines > 0 && newStart === 0) throw fail('malformed new start');
    const start = oldLines === 0 ? oldStart : oldStart - 1;
    if (start < cursor) throw fail('overlapping or out-of-order hunk');
    if (start + oldLines > a.length) throw fail('old range exceeds input');
