'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Int32Array(b.length + 1));
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
  return dp[a.length][b.length];
}
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alph = ['', 'x', 'y', ' x', '-x', '+x', 'z'];
for (let t = 0; t < 30000; t++) {
  const gen = () => Array.from({ length: rnd(14) }, () => alph[rnd(1 + rnd(alph.length))]);
  const a = gen(), b = gen();
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const edits = s.filter((e) => e.op !== 'equal').length;
  assert.equal(edits, a.length + b.length - 2 * lcs(a, b), JSON.stringify([a, b]));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  for (const context of [0, 1, 2, 3]) {
    const h = unifiedHunks(a, b, { context });
    assert.deepEqual(applyHunks(a, h), b);
    if (a.join('\n') === b.join('\n') && a.length === b.length) assert.deepEqual(h, []);
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}
// zero-line coordinates
assert.deepEqual(unifiedHunks(['a'], ['n', 'a'], { context: 0 }), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+n'] }]);
assert.deepEqual(unifiedHunks(['a', 'b'], ['b'], { context: 0 }), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-a'] }]);
assert.deepEqual(unifiedHunks(['a', 'b'], ['a', 'b', 'c'], { context: 0 }), [{ oldStart: 2, oldLines: 0, newStart: 3, newLines: 1, lines: ['+c'] }]);
// apply errors
assert.throws(() => applyHunks(['a'], [{ oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: ['-b', '+c'] }]), /hunk 0 does not apply/);
const h2 = unifiedHunks(['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'], ['A', 'b', 'c', 'd', 'e', 'f', 'g', 'H'], { context: 1 });
assert.equal(h2.length, 2);
assert.throws(() => applyHunks(['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'], [h2[1], h2[0]]), /hunk 1 does not apply/);
// perf
const big = Array.from({ length: 20000 }, (_, i) => `line ${i % 50}`);
const big2 = big.slice(); big2[100] = 'changed'; big2.splice(15000, 3); big2.splice(7000, 0, 'new', 'lines');
let t0 = performance.now();
const hh = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hh), big2);
console.log('small change ms', (performance.now() - t0).toFixed(1));
t0 = performance.now();
diffLines(big, big);
console.log('identical ms', (performance.now() - t0).toFixed(1));
const rep = Array(20000).fill('same'); const rep2 = rep.slice(); rep2.splice(10000, 5); rep2.splice(500, 0, 'x');
t0 = performance.now();
assert.deepEqual(applyHunks(rep, unifiedHunks(rep, rep2)), rep2);
console.log('repetitive ms', (performance.now() - t0).toFixed(1));
const r1 = Array.from({ length: 3000 }, () => 'l' + rnd(30)), r2 = Array.from({ length: 3000 }, () => 'l' + rnd(30));
t0 = performance.now();
const sr = diffLines(r1, r2);
console.log('random 3000 ms', (performance.now() - t0).toFixed(1), sr.filter((e) => e.op !== 'equal').length === 6000 - 2 * lcs(r1, r2));
console.log('ok');

